import json

with open("benchmark/source_brief.md", "r", encoding="utf-8") as f:
    text = f.read()

# Extract top 20
top20 = []
for line in text.splitlines():
    m = re.match(r'^\|\s*(\d+)\s*\|\s*(\d+)\s*\|\s*([^|]+)\s*\|\s*([\d.%]+)\s*\|\s*([+\-\d.%]+)\s*\|$', line)
    if m:
        top20.append([m.group(1), m.group(2), m.group(3).strip(), m.group(4).strip(), m.group(5).strip()])

# Extract long term history
