    if "Very Long Term History:" in line:
        in_history = True
    if in_history and line.startswith("|") and not "---" in line and not "Very" in line and not "Language" in line:
        cols = [c.strip() for c in line.split("|")[1:-1]]
        if cols and len(cols) == 10:
            history.append(cols)
    if in_history and line.startswith("This table reveals"):
        break

# Extract Hall of fame
hof = []
in_hof = False
for line in text.splitlines():
    if "Programming Language Hall of Fame" in line:
        in_hof = True
    if in_hof and line.startswith("|") and not "---" in line and not "Year" in line:
        cols = [c.strip() for c in line.split("|")[1:-1]]
        if cols and len(cols) == 2:
            hof.append(cols)
    if in_hof and line.startswith("Python has won"):
        break

with open("data.json", "w") as f:
    json.dump({
        "top20": top20,
        "history": history,
        "hof": hof
    }, f, indent=2)

